  split.recipients[0] = builderRecipient;
  split.amounts[0] = (_finalBidAmount * builderRewardsBPS) / BPS_PER_100_PERCENT;

  // Set referral reward
  split.recipients[1] = _currentBidRefferal != address(0) ? _currentBidRefferal : builderRecipient;
